contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address callee, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        uint balBefore = address(this).balance;
        bool reverted;
        // perform the call and capture whether it reverted
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = address(this).balance;
        // General rule: balance never increases; if it decreased then forward did not revert
        assert(balAfter <= balBefore && (balAfter < balBefore ? reverted == false : true));
    }
    receive() external payable { }
}

